// Cache des listes d'équipes par championnat (pour résoudre les IDs ESPN)
var _espnTeamsCache = {};

function espnLeagueOf(nom) {
  if(ESPN_TEAM_LEAGUE[nom]) return ESPN_TEAM_LEAGUE[nom];
  var low = (nom||'').toLowerCase();
  for(var k in ESPN_TEAM_LEAGUE){ if(low.indexOf(k.toLowerCase())>=0 || k.toLowerCase().indexOf(low)>=0) return ESPN_TEAM_LEAGUE[k]; }
  return null;
}

// Résoudre l'ID ESPN d'une équipe via la liste des équipes de son championnat
// Charge (et cache) la liste des équipes d'un championnat ESPN
async function _espnLoadLeagueTeams(league) {
  if(_espnTeamsCache[league]) return _espnTeamsCache[league];
  try {
    var r = await fetch(FD_PROXY+'?host=espn&path='+encodeURIComponent('/apis/site/v2/sports/soccer/'+league+'/teams'));
    var d = await r.json();
    var list = (d.sports && d.sports[0] && d.sports[0].leagues && d.sports[0].leagues[0] && d.sports[0].leagues[0].teams) ? d.sports[0].leagues[0].teams : [];
    _espnTeamsCache[league] = list.map(function(t){ return t.team; });
  } catch(e) { _espnTeamsCache[league] = []; }
  return _espnTeamsCache[league];
}

// Cherche une équipe dans une liste. mode='exact' (displayName/name/abbr) ou 'partial' (inclusion)
function _espnMatchTeam(nom, teams, league, mode) {
  var low = (nom||'').toLowerCase();
  var best = null;
  if(mode === 'exact') {
    for(var i=0;i<teams.length;i++){
      var t = teams[i];
      var cands = [t.displayName, t.name, t.shortDisplayName, t.location, t.abbreviation].filter(Boolean).map(function(x){return x.toLowerCase();});
      if(cands.indexOf(low)>=0){ best=t; break; }
    }
  } else {
    for(var j=0;j<teams.length;j++){
      var t2 = teams[j];
      var cands2 = [t2.displayName, t2.name, t2.shortDisplayName, t2.location].filter(Boolean).map(function(x){return x.toLowerCase();});
      if(cands2.some(function(c){ return c.length>2 && (c.indexOf(low)>=0 || (low.length>2 && low.indexOf(c)>=0)); })){ best=t2; break; }
    }
  }
  return best ? {id:best.id, league:league, name:best.displayName, logo:(best.logos&&best.logos[0]&&best.logos[0].href)||''} : null;
}

// Résout l'équipe ESPN. Essaie le championnat deviné, sinon TOUS les championnats connus.
/* Identifiants ESPN forces.
   POURQUOI : la resolution normale passe par /soccer/{ligue}/teams, la LISTE des
   clubs. Or ESPN sert ce point d'entree SANS en-tete Access-Control-Allow-Origin,
   alors que /teams/{id}/schedule en envoie un. Depuis le navigateur, la liste est
   donc inaccessible et aucun club non deja mis en cache ne peut etre resolu.
   Les clubs listes ici court-circuitent cette etape. Verifie le 06/08/2026 :
   arg.1/teams/5/schedule renvoie bien 20 matchs pour Boca. */
var ESPN_TEAM_ID_FIX = {
  'boca juniors':  {id:'5',     league:'arg.1'},
  'boca':          {id:'5',     league:'arg.1'},
  /* Identifiants relevés le 06/08/2026 dans la réponse /pdebug du Worker, qui
     liste les équipes suivies avec leur id ESPN et leur ligue. Sans eux, vider
     les clés espn_teamid_any_* du localStorage suffit à rendre ces clubs
     introuvables, puisque la résolution par nom passe par /{ligue}/teams, servi
     sans en-tête CORS. */
  'miami cf':      {id:'20232', league:'usa.1'},
  'inter miami':   {id:'20232', league:'usa.1'},
  'inter miami cf':{id:'20232', league:'usa.1'},
  'palmeiras':     {id:'2029',  league:'bra.1'},
  'se palmeiras':  {id:'2029',  league:'bra.1'},
  'france':        {id:'478',   league:'fifa.world'},
  'inter milan':   {id:'110',   league:'ita.1'},
  'lyon':          {id:'167',   league:'fra.1'},
  'psg':           {id:'160',   league:'fra.1'},
  'psv':           {id:'148',   league:'ned.1'},
  'real madrid':   {id:'86',    league:'esp.1'},
  'bayern munich': {id:'132',   league:'ger.1'},
  'arsenal':       {id:'359',   league:'eng.1'}
};

async function espnResolveTeam(nom) {
  var _fix = ESPN_TEAM_ID_FIX[String(nom||'').toLowerCase().trim()];
  if(_fix) return {id:_fix.id, league:_fix.league, name:nom, logo:''};
  var nomKey = (nom||'').toLowerCase().replace(/\s+/g,'_');
  try { var cached = localStorage.getItem('espn_teamid_any_'+nomKey); if(cached){ var ci=JSON.parse(cached); if(ci&&ci.id) return ci; } } catch(e){}

  // Ordre : championnat deviné en premier, puis tous les championnats connus (dédupliqués)
  var order = [];
  var guess = espnLeagueOf(nom);
  if(guess) order.push(guess);
  try { for(var k in ESPN_TEAM_LEAGUE){ var lg=ESPN_TEAM_LEAGUE[k]; if(order.indexOf(lg)<0) order.push(lg); } } catch(e){}

  // 2 passes : match exact sur tous les championnats, puis match partiel sur tous
  for(var pass=0; pass<2; pass++){
    var mode = pass===0 ? 'exact' : 'partial';
    for(var i=0;i<order.length;i++){
      var teams = await _espnLoadLeagueTeams(order[i]);
      var resolved = _espnMatchTeam(nom, teams, order[i], mode);
      if(resolved){ try { localStorage.setItem('espn_teamid_any_'+nomKey, JSON.stringify(resolved)); } catch(e){} return resolved; }
    }
  }
  return null;
}

// Convertir cote américaine → décimale (réutilise americanToDecimal si déjà défini plus bas)
function _espnAmDec(am){ am=parseFloat(am); if(isNaN(am)) return null; var d=am>0?(am/100+1):(100/Math.abs(am)+1); return d.toFixed(2); }

// Récupérer résultats + cotes d'un club via ESPN
// season : année de début de saison (2025 = saison 2025-26). Par défaut saison courante.
async function espnClubSchedule(nom, season, leagueSlug) {
  var resolved = await espnResolveTeam(nom);
  if(!resolved) return null;
  try {
    var schedPath = '/apis/site/v2/sports/soccer/'+(leagueSlug||resolved.league)+'/teams/'+resolved.id+'/schedule';
    if(season) schedPath += '?season='+season;
    var r = await fetch(FD_PROXY+'?host=espn&path='+encodeURIComponent(schedPath));
    var d = await r.json();
    var events = d.events || [];
    var matches = events.map(function(e){
      var comp = (e.competitions && e.competitions[0]) ? e.competitions[0] : null;
      if(!comp) return null;
      var home = comp.competitors.find(function(c){return c.homeAway==='home';}) || comp.competitors[0];
      var away = comp.competitors.find(function(c){return c.homeAway==='away';}) || comp.competitors[1];
      var st = comp.status && comp.status.type ? comp.status.type : {};
      var completed = !!st.completed;
      var hS = home.score ? parseInt(home.score.value!==undefined?home.score.value:home.score) : null;
      var aS = away.score ? parseInt(away.score.value!==undefined?away.score.value:away.score) : null;
      // Cotes
      var odds=null;
      try {
        if(comp.odds && comp.odds.length && comp.odds[0]){
          var o=comp.odds[0], mlo=o.moneyline||{};
          var ho=(mlo.home&&mlo.home.close&&mlo.home.close.odds!=null)?mlo.home.close.odds:null;
          var ao=(mlo.away&&mlo.away.close&&mlo.away.close.odds!=null)?mlo.away.close.odds:null;
          var dr=(mlo.draw&&mlo.draw.close&&mlo.draw.close.odds!=null)?mlo.draw.close.odds:((o.drawOdds&&o.drawOdds.moneyLine!=null)?o.drawOdds.moneyLine:null);
          var ov=(o.total&&o.total.over&&o.total.over.close&&o.total.over.close.odds!=null)?o.total.over.close.odds:null;
          var un=(o.total&&o.total.under&&o.total.under.close&&o.total.under.close.odds!=null)?o.total.under.close.odds:null;
          var rl=(o.total&&o.total.over&&o.total.over.close&&o.total.over.close.line!=null)?o.total.over.close.line:(o.overUnder!=null?o.overUnder:null);
          var ouL=(rl!=null)?String(rl).replace(/^[ou]/i,''):null;
          if(ho!=null||ao!=null||dr!=null||ov!=null) odds={home:_espnAmDec(ho),away:_espnAmDec(ao),draw:_espnAmDec(dr),over:_espnAmDec(ov),under:_espnAmDec(un),ouLine:ouL};
        }
      } catch(oe){ odds=null; }
      return {
        id: e.id,
        date: e.date,
        completed: completed,
        homeTeam: home.team ? home.team.displayName : '?',
        awayTeam: away.team ? away.team.displayName : '?',
        homeId: home.team ? String(home.team.id) : null,
        awayId: away.team ? String(away.team.id) : null,
        homeScore: hS, awayScore: aS,
        competition: (e.season && e.season.slug) ? e.season.slug : (leagueSlug||resolved.league),
        competitionName: (e.season && e.season.name) ? e.season.name : '',
        odds: odds,
        venue: (comp.venue && comp.venue.fullName) ? comp.venue.fullName : ''
      };
    }).filter(Boolean);
    return {team:resolved, matches:matches};
  } catch(e) { return null; }
}


// Convertir un match ESPN au format football-data (pour renderSaisonsChart)
function espnToFdMatch(m, ourName, ourFdId) {
  // Déterminer le type de compétition à partir du slug/nom ESPN
  var slug = (m.competition||'').toLowerCase();
  var cname = m.competitionName || '';
  var type = 'LEAGUE';
  // Slugs de championnats nationaux : fra.1, eng.1, ita.1, esp.1, ger.1, por.1, ned.1, bra.1...
  var isLeague = /\.(1|2)$/.test(slug) || slug.indexOf('league')>=0;
  // Coupes d'Europe
  if(slug.indexOf('uefa')>=0 || slug.indexOf('champions')>=0 || slug.indexOf('europa')>=0 || slug.indexOf('conference')>=0 ||
     cname.indexOf('Champions')>=0 || cname.indexOf('Europa')>=0 || cname.indexOf('UEFA')>=0 || cname.indexOf('Conference')>=0) {
    type = 'CUP';
  } else if(slug.indexOf('cup')>=0 || slug.indexOf('coupe')>=0 || slug.indexOf('copa')>=0 || slug.indexOf('dfb')>=0 ||
            /* PIEGE : 'coppa_italia' ne contient PAS 'copa' (deux p), 'ned.cup' passe mais
               'knvb'/'beker'/'taca' non, et les coupes continentales hors Europe non plus.
               Sans ces motifs, le match tombait dans le `else` final et etait etiquete
               « Championnat » : 5 matchs de Coppa comptes en Serie A, aucune chip affichee. */
            slug==='eng.fa' || slug.indexOf('.fa_')>=0 ||
            slug.indexOf('coppa')>=0 || slug.indexOf('pokal')>=0 || slug.indexOf('beker')>=0 ||
            slug.indexOf('knvb')>=0 || slug.indexOf('taca')>=0 || slug.indexOf('open')>=0 ||
            slug.indexOf('libertadores')>=0 || slug.indexOf('sudamericana')>=0 ||
            slug.indexOf('concacaf')>=0 || slug.indexOf('afc.')>=0 || slug.indexOf('nations')>=0 ||
            cname.indexOf('Cup')>=0 || cname.indexOf('Coupe')>=0 || cname.indexOf('Copa')>=0 ||
            cname.indexOf('Coppa')>=0 || cname.indexOf('Pokal')>=0 || cname.indexOf('Beker')>=0) {
    type = 'CUP';
  } else if(isLeague) {
    type = 'LEAGUE';
  } else {
    type = 'LEAGUE'; // par défaut championnat (slugs nationaux)
  }

  // Nom lisible de la compétition (les coupes d'Europe doivent contenir Champions/Europa/Conference
  // pour être bien classées en « Coupe Europe » au lieu de « Coupe Nationale »)
  var compName = cname;
  if(!compName){
    if(slug.indexOf('afc.champions')>=0) compName = 'AFC Champions';
    else if(slug.indexOf('concacaf.champions')>=0) compName = 'CONCACAF Champions';
    else if(slug.indexOf('nations')>=0) compName = 'Ligue des Nations';
    else if(slug.indexOf('champions')>=0) compName = 'Ligue des Champions';
    else if(slug.indexOf('conference')>=0 || slug.indexOf('europa.conf')>=0) compName = 'Conference League';
    else if(slug.indexOf('europa')>=0) compName = 'Ligue Europa';
    /* Libelles des coupes cablees en aout 2026 : sans eux, toutes s'afficheraient
       sous un « Coupe » generique et se confondraient dans les chips. */
    else if(slug.indexOf('coppa_italia')>=0) compName = 'Coppa Italia';
    else if(slug.indexOf('coupe_de_france')>=0) compName = 'Coupe de France';
    else if(slug.indexOf('copa_del_rey')>=0) compName = 'Copa del Rey';
    else if(slug.indexOf('dfb_pokal')>=0) compName = 'DFB Pokal';
    else if(slug==='eng.fa') compName = 'FA Cup';
    else if(slug.indexOf('league_cup')>=0) compName = 'Carabao Cup';
    else if(slug==='ned.cup') compName = 'KNVB Beker';
    else if(slug.indexOf('copa_do_brazil')>=0) compName = 'Copa do Brasil';
    else if(slug==='arg.copa') compName = 'Copa Argentina';
    else if(slug.indexOf('leagues.cup')>=0) compName = 'Leagues Cup';
    else if(slug.indexOf('usa.open')>=0) compName = 'US Open Cup';
    else if(slug.indexOf('libertadores')>=0) compName = 'Libertadores';
    else if(slug.indexOf('sudamericana')>=0) compName = 'Sudamericana';
    else if(slug.indexOf('concacaf.champions')>=0) compName = 'CONCACAF Champions';
    else if(slug.indexOf('afc.champions')>=0) compName = 'AFC Champions';
    else if(slug.indexOf('nations')>=0) compName = 'Ligue des Nations';
    else compName = (type==='LEAGUE' ? 'Championnat' : 'Coupe');
  }

  // Déterminer de quel côté est notre équipe (pour domicile/extérieur)
  /* ACCENTS — bug trouve le 15/08 sur l'Atletico Madrid.
     Le nom stocke porte l'accent (« atletico madrid »), celui d'ESPN non. Le
     test d'egalite echouait donc, et les deux camps ne marquaient plus que 10
     via le mot commun « madrid » : egalite, et le repli « on garde domicile »
     classait les DEPLACEMENTS au Bernabeu comme des receptions.
     Meme famille que le bug PSG/Paris FC, autre cause. On normalise les trois
     chaines avant toute comparaison. */
  var _sansAcc = function (x) {
    return String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  };
  var nl = _sansAcc(ourName);
  var homeLow = _sansAcc(m.homeTeam);
  var awayLow = _sansAcc(m.awayTeam);
  // Score de similarité : combien de mots du nom de l'équipe se retrouvent dans home/away
  function simScore(teamNameLow, ourLow){
    if(teamNameLow===ourLow) return 100;
    if(teamNameLow.indexOf(ourLow)>=0 || ourLow.indexOf(teamNameLow)>=0) return 50;
    /* ABREVIATIONS. Le filtre « mots de plus de 3 lettres » ecartait entierement
       un nom comme « PSG » : les deux scores tombaient a 0, et le repli
       « on garde home par defaut » collait l'identifiant du PSG a PARIS FC,
       l'equipe qui recevait. Resultat : filtre domicile/exterieur a 0 match et
       des NaN partout. On compare donc aussi les INITIALES. */
    var mots = teamNameLow.split(/[^a-z0-9]+/).filter(Boolean);
    var initiales = mots.map(function(w){ return w.charAt(0); }).join('');
    if(ourLow.length <= 4 && ourLow.replace(/[^a-z0-9]/g,'') === initiales) return 90;
    // mots communs significatifs (3 lettres ou plus)
    var words = ourLow.split(/\s+/).filter(function(w){return w.length>=3;});
    var hits = words.filter(function(w){ return teamNameLow.indexOf(w)>=0; }).length;
    return hits>0 ? 10*hits : 0;
  }
  var homeSim = simScore(homeLow, nl);
  var awaySim = simScore(awayLow, nl);
  var weAreHome = homeSim >= awaySim && homeSim > 0;
  // Si aucun des deux ne matche, on garde home par défaut (rare)
  if(homeSim===0 && awaySim===0) weAreHome = true;
  var homeId = weAreHome ? ourFdId : ('espn_'+(m.homeTeam||'h'));
  var awayId = weAreHome ? ('espn_'+(m.awayTeam||'a')) : ourFdId;

  return {
    utcDate: m.date,
    status: m.completed ? 'FINISHED' : 'SCHEDULED',
    competition: { name: compName, type: type, code: m.competition || '' },
    homeTeam: { id: homeId, name: m.homeTeam, shortName: m.homeTeam },
    awayTeam: { id: awayId, name: m.awayTeam, shortName: m.awayTeam },
    score: {
      fullTime: { home: m.homeScore, away: m.awayScore },
      regularTime: { home: m.homeScore, away: m.awayScore }
    },
    odds: m.odds || null,
    espnId: m.id || ''
  };
}

/* ── SAISONS ── */
var _currentSaison = localStorage.getItem('g45_saison_active') || '2526';
