function addUnit(){
  var name=($i('u-name')&&$i('u-name').value||'').trim();if(!name)return;
  var color=$i('u-color').value||selColor||PCOLS[0];
  var pending=window._pendingLogo&&window._pendingLogo.name===name?window._pendingLogo:null;
  var abbr=pending?pending.abbr:name.substring(0,3).toUpperCase();
  var logoUrl=pending?pending.url:(LOGOS[name]||null);
  if(pending&&pending.color)color=pending.color;
  if(state.u.find(function(u){return u.n===name;}))return alert('Existe déjà !');
  var ulink=($i('u-link')&&$i('u-link').value.trim())||'';
  var ulink2=($i('u-link2')&&$i('u-link2').value.trim())||'';
  var unote=($i('u-note')&&$i('u-note').value.trim())||'';var utype=($i('u-type')&&$i('u-type').value)||'club';
try{ var _off2=JSON.parse(localStorage.getItem('g45_presets_off')||'{}'); if(_off2[name]){ delete _off2[name]; localStorage.setItem('g45_presets_off',JSON.stringify(_off2)); } }catch(e){}
state.u.push({n:name,abbr:abbr,color:color,s:$i('u-stars').value,l:1,sport:($i('u-sport')&&$i('u-sport').value)||'⚽',logoUrl:logoUrl||'',link:ulink,link2:ulink2,note:unote,type:utype});
  if(logoUrl)LOGOS[name]=logoUrl;
  $i('u-name').value='';
  if($i('u-link'))$i('u-link').value='';
  if($i('u-link2'))$i('u-link2').value='';
  $i('search-results').innerHTML='';
  window._pendingLogo=null;
  save();
  /* La synchro GitHub écrase TOUT l'état local (mur compris) quand la version distante est
     plus récente, et `save()` ne déclenche qu'un envoi différé de 2,5 s. Un ajout au mur
     suivi d'un rechargement partait donc à la poubelle. On force l'envoi immédiat. */
  try{ if(typeof _g45PushBetsGithub==='function') _g45PushBetsGithub(true); }catch(e){}
}
function editUnit(i){
  var u=state.u[parseInt(i)];if(!u)return;
  var m=$i('edit-unit-modal');if(!m)return;
  $i('edit-unit-idx').value=i;
  $i('edit-unit-name').value=u.n||'';
  $i('edit-unit-stars').value=u.s||'3';
  $i('edit-unit-note').value=u.note||'';
  $i('edit-unit-color').value=u.color||'#4d84ff';
  m.style.display='flex';
}
function closeEditUnit(){var m=$i('edit-unit-modal');if(m)m.style.display='none';}
function saveEditUnit(){
  var e=$i('edit-unit-idx');
  var i=parseInt(e?e.value:'');
  var u=(!isNaN(i))?state.u[i]:null;
  if(!u){ console.warn('saveEditUnit : entrée introuvable (index '+(e?e.value:'?')+')'); closeEditUnit(); return; }
  var vn=$i('edit-unit-name'), vs=$i('edit-unit-stars'), vt=$i('edit-unit-note'), vc=$i('edit-unit-color');
  /* Le nom n'est plus forcé en majuscules : « Haaland » restait lisible, « HAALAND » non,
     et un renommage casse le lien avec les paris déjà enregistrés sous l'ancien nom. */
  var newName=((vn&&vn.value)||u.n||'').trim();
  if(newName) u.n=newName;
  if(vs&&vs.value) u.s=vs.value;
  if(vt) u.note=(vt.value||'').trim();
  if(vc&&vc.value) u.color=vc.value;
  /* Le rendu ne doit jamais empêcher la fermeture du modal : une exception ici donnait
     l'impression que le bouton Enregistrer ne faisait rien, alors que la sauvegarde
     avait bien eu lieu. */
  try{ save(); }catch(err){ console.warn('saveEditUnit / save', err); }
  try{ render(); }catch(err){ console.warn('saveEditUnit / render', err); }
  try{ if(typeof _g45PushBetsGithub==='function') _g45PushBetsGithub(true); }catch(err){}
  closeEditUnit();
}
function rmUnit(i){var u=state.u[parseInt(i)];if(u&&confirm('Supprimer '+u.n+' ?')){
  /* PIERRE TOMBALE : on memorise TOUTE suppression, pas seulement les PRESET.
     Deux mecanismes ressuscitaient les entrees effacees — le bloc PRESETS au
     demarrage, et la fusion ADDITIVE du pull GitHub qui reinjecte ce qui est
     absent d'un cote. Sans trace ecrite, une suppression ne peut pas survivre
     a une synchronisation. */
  try{ var _off=JSON.parse(localStorage.getItem('g45_presets_off')||'{}'); _off[u.n]=Date.now(); localStorage.setItem('g45_presets_off',JSON.stringify(_off)); }catch(e){}
  state.u.splice(parseInt(i),1);save();try{ if(typeof _g45PushBetsGithub==='function') _g45PushBetsGithub(true); }catch(e){}}}

