var _multiSelected=null;
function toggleCurvePicker(){
  var p=$i('curve-picker');if(!p)return;
  var open=p.style.display==='block';
  p.style.display=open?'none':'block';
  if(!open){renderCurvePicker();setTimeout(function(){document.addEventListener('click',function h(e){var btn=$i('curve-picker-btn'),pk=$i('curve-picker');if(pk&&btn&&!pk.contains(e.target)&&!btn.contains(e.target)){pk.style.display='none';document.removeEventListener('click',h);}});},50);}
}
function renderCurvePicker(){
  var list=$i('curve-picker-list');if(!list)return;
  if(!_multiSelected)_multiSelected={};
  var teams=state.u.filter(function(u){return state.a.some(function(h){return h.n===u.n;});});
  var cnt=Object.values(_multiSelected).filter(Boolean).length;
  list.innerHTML=teams.map(function(u){
    var on=!!_multiSelected[u.n];var dis=!on&&cnt>=5;
    var sn=u.n.replace(/"/g,'&quot;');
    var esc=sn.replace(/"/g,'&quot;');
    return '<label style="display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--b1);cursor:'+(dis?'not-allowed':'pointer')+';opacity:'+(dis?'.45':'1')+';">'
      +'<input type="checkbox" '+(on?'checked':'')+' '+(dis&&!on?'disabled':'')+' data-nom="'+sn+'" onchange="toggleCurveTeam(this)" style="accent-color:'+(u.color||'#4d84ff')+';width:15px;height:15px;flex-shrink:0;">'
      +'<input type="color" value="'+(u.color||'#4d84ff')+'" title="Changer couleur" data-nom="'+sn+'" onchange="changeCurveColor(this)" onclick="event.stopPropagation();" style="width:18px;height:18px;border-radius:50%;border:none;padding:0;cursor:pointer;flex-shrink:0;background:none;">'
      +'<span style="font-size:12px;font-weight:600;flex:1;">'+u.n+'</span>'
      +(on?'<span style="font-size:9px;color:'+(u.color||'#4d84ff')+';font-weight:700;">✓</span>':'')+'</label>';
  }).join('');
  var btn=$i('curve-picker-btn');if(btn)btn.textContent='⚙️ '+cnt+'/5';
}
function changeCurveColor(el){
  var nom=el.dataset.nom;var col=el.value;
  var u=state.u.find(function(x){return x.n===nom;});
  if(u){u.color=col;save();}
  if(_multiSelected&&_multiSelected[nom])renderMultiCurveChart();
  renderCurvePicker();
}
function toggleCurveTeam(el){
  var nom=el.dataset.nom;var checked=el.checked;
  if(!_multiSelected)_multiSelected={};
  var cnt=Object.values(_multiSelected).filter(Boolean).length;
  if(checked&&cnt>=5){el.checked=false;renderCurvePicker();return;}
  _multiSelected[nom]=checked;renderCurvePicker();renderMultiCurveChart();
}
var _gcMToken=(typeof _gcMToken!=='undefined')?_gcMToken:0;
function renderMultiCurveChart(){
  var ctx=$i('chart-multi');if(!ctx)return;
  if(window._gcM){try{window._gcM.destroy();}catch(e){}}window._gcM=null;
  var leg=$i('chart-multi-legend');if(leg)leg.innerHTML='';
  /* JETON ANTI-CHEVAUCHEMENT (31/08). BUG : "Canvas is already in use" — la
     creation du graphique est differee de 80ms plus bas, donc deux appels
     rapproches de `renderMultiCurveChart()` (typiquement plusieurs scores de
     paris qui se resolvent presque en meme temps et redessinent chacun le
     Bilan) programment chacun leur propre `new Chart(...)` sur LE MEME
     canvas, sans que le destroy() du second ait pu voir le chart cree par le
     premier — il n'existe pas encore au moment ou ce destroy() s'execute.
     Seul le DERNIER appel en date doit reellement creer le graphique ; les
     autres se desistent silencieusement. */
  var _meJeton=++_gcMToken;
  var all=[];
  state.u.forEach(function(u){
    var paris=state.a.filter(function(h){return h.n===u.n;});if(!paris.length)return;
    var cum=0;
    var dlabels=['Départ'].concat(_g45Chrono(paris).map(function(h){var adv4=h.target&&h.target!=='-'?h.target:'';return (h.date||'')+(adv4?' vs '+adv4:'')+(h.l?' P'+h.l:'');}));
    var data=[0].concat(_g45Chrono(paris).map(function(h){cum+=(h.win?(parseFloat(h.m)*parseFloat(h.cote))-parseFloat(h.m):-parseFloat(h.m));return parseFloat(cum.toFixed(2));}));
    var _c=u.color&&all.every(function(x){return x._color!==u.color;})?u.color:CURVE_COLS[all.length%CURVE_COLS.length];
    all.push({label:u.n,data:data,_labels:dlabels,borderColor:_c,backgroundColor:'transparent',borderWidth:1.5,tension:.4,pointRadius:3,pointHoverRadius:10,pointHoverBorderColor:'#fff',pointHoverBorderWidth:2,pointHitRadius:30,_color:_c});
  });
  if(!all.length){if(leg)leg.innerHTML='<span style="font-size:11px;color:var(--t3);">Aucun historique</span>';return;}
  if(!_multiSelected)_multiSelected={};
  /* Auto-sélectionner top 5 si premier chargement ou nouvelles équipes */
  var hasSelection=Object.values(_multiSelected).some(Boolean);
  if(!hasSelection){
    var sorted=all.slice().sort(function(a,b){return (b.data[b.data.length-1]||0)-(a.data[a.data.length-1]||0);});
    sorted.forEach(function(d,i){_multiSelected[d.label]=i<5;});
  } else {
    all.forEach(function(d){if(_multiSelected[d.label]===undefined)_multiSelected[d.label]=false;});
  }
  var active=all.filter(function(d){return _multiSelected[d.label];});
  if(leg)leg.innerHTML=active.map(function(d){return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:700;color:var(--t2);white-space:nowrap;flex-shrink:0;"><span style="display:inline-block;width:10px;height:3px;border-radius:2px;background:'+d._color+';"></span>'+d.label+'</span>';}).join('');
  var btn=$i('curve-picker-btn');if(btn)btn.textContent='⚙️ '+active.length+'/5';
  if(!active.length)return;
  var maxLen=active.reduce(function(m,d){return Math.max(m,d.data.length);},0);
  active.forEach(function(d){while(d.data.length<maxLen)d.data.push(null);});
  setTimeout(function(){
    if(_meJeton!==_gcMToken)return;   // un appel plus recent a pris le relais
    if(!$i('chart-multi'))return;
    if(window._gcM){try{window._gcM.destroy();}catch(e){}}window._gcM=null;
    var ct=$i('chart-multi').getContext('2d');
    /* AXE DES DATES, EN APPROXIMATION ASSUMEE (01/09, retour d'Antoine). Ici,
       contrairement au Bilan/Bankroll, chaque equipe a SA PROPRE sequence de
       dates (le point d'index 5 de Real Madrid n'est pas force le meme jour
       que le point d'index 5 du PSG) — il n'existe pas de "vraie" date par
       position d'index commune a toutes les courbes. On prend donc la date de
       la courbe la PLUS LONGUE comme reperage indicatif — utile pour se
       reperer dans le temps, mais a lire comme approximatif sur les equipes
       plus courtes, pas comme une date exacte pour chacune. */
    var refLbl=active.reduce(function(best,d){ return (d._labels&&d._labels.length>(best?best.length:0))?d._labels:best; },null)||[];
    window._gcM=new Chart(ct,{type:'line',data:{labels:Array.from({length:maxLen},function(_,i){return i;}),datasets:active},options:{
      animation:false,responsive:true,maintainAspectRatio:false,interaction:{mode:'nearest',intersect:false},
      plugins:{legend:{display:false},tooltip:{backgroundColor:'rgba(8,11,18,.96)',borderColor:'rgba(255,255,255,.1)',borderWidth:1,
        callbacks:{title:function(ii){var d=active[0];return d&&d._labels?d._labels[ii[0].dataIndex]||'':'';},label:function(i){return ' '+i.dataset.label+' : '+(i.raw!==null?(i.raw>=0?'+':'')+i.raw.toFixed(2)+'€':'—');}}}},
      scales:{x:{display:true,grid:{display:false},ticks:{color:'#e8ecfa',font:{size:8},maxTicksLimit:5,maxRotation:0,autoSkip:true,callback:(function(){var last=null;return function(v,index){var lbl=refLbl[index];var d=lbl?lbl.split(' ')[0]:'';if(!d||d===last)return '';last=d;return d;};})()}},y:{grid:{color:'rgba(255,255,255,.03)'},border:{display:false},ticks:{color:'#e8ecfa',font:{size:9},maxTicksLimit:4,callback:function(v){return v+'€';}}}}
    }});
    attachTouchTooltip('chart-multi',function(){return window._gcM;},'cib-multi','cib-multi-txt','cib-multi-val');
  },80);
}
function renderGlobalCharts(){
  try{renderBilanTypeFilter();}catch(e){} try{renderBilanCompFilter();}catch(e){} try{renderBilanBookFilter();}catch(e){}
  renderGlobalChart();
  setTimeout(function(){
    renderMultiCurveChart();
    renderBooksChart();
    renderPaliersChart();
    setTimeout(function(){renderRadarChart();renderChartMoisBar();renderChartSport();renderChartTypeBen();renderChartTypeDonut();renderStreakPanel();},200);
  },100);
}

function renderBooksChart(){
  var ctx=$i('chart-books');if(!ctx)return;
  if(GC2.books){try{GC2.books.destroy();}catch(e){}}
  var total=Object.values(state.b).reduce(function(a,v){var n=parseFloat(v);return a+(isNaN(n)?0:n);},0);
  if(total<=0){ctx.parentElement.innerHTML='<div class="empty">Aucun solde</div>';return;}
  var labels=[],data=[],colors=[];
  Object.entries(state.b).forEach(function(e){
    var v=parseFloat(e[1]||0);
    if(v>0){labels.push(bki(e[0]).n);data.push(v);colors.push(bki(e[0]).c);}
  });
  if(!data.length){ctx.parentElement.innerHTML='<div class="empty">Aucun solde positif</div>';return;}
  GC2.books=new Chart(ctx.getContext('2d'),{
    type:'doughnut',
    data:{labels:labels,datasets:[{data:data,backgroundColor:colors.map(function(c){return c+'aa';}),borderColor:colors,borderWidth:1,hoverOffset:4}]},
    options:{
      responsive:true,maintainAspectRatio:false,cutout:'65%',
      plugins:{
        legend:{display:true,position:'right',labels:{color:'#8b97c4',font:{size:10},boxWidth:10,padding:8}},
        tooltip:{backgroundColor:'rgba(8,11,18,.96)',callbacks:{label:function(i){return i.label+': '+i.raw.toFixed(2)+'€ ('+((i.raw/total)*100).toFixed(1)+'%)';}}}
      }
    }
  });
}

/* SELECTEUR D'EQUIPES (01/09, retour d'Antoine : "rajouter un selectif
   equipes et en mettre moins") — meme mecanisme que le picker deja existant
   sur "Profit par equipe" (`_multiSelected`/`toggleCurvePicker`), duplique a
   l'identique pour ce graphique avec son propre etat (`_paliersSelected`) et
   son propre plafond (8, plus genereux que les 5 de l'autre picker puisque
   les barres horizontales supportent mieux davantage de lignes). */
var _paliersSelected=null;
function togglePaliersPicker(){
  var p=$i('paliers-picker');if(!p)return;
  var open=p.style.display==='block';
  p.style.display=open?'none':'block';
  if(!open){renderPaliersPicker();setTimeout(function(){document.addEventListener('click',function h(e){var btn=$i('paliers-picker-btn'),pk=$i('paliers-picker');if(pk&&btn&&!pk.contains(e.target)&&!btn.contains(e.target)){pk.style.display='none';document.removeEventListener('click',h);}});},50);}
}
window.togglePaliersPicker=togglePaliersPicker;
function _paliersEquipesActives(){
  var all=state.u;
  if(!_paliersSelected)_paliersSelected={};
  var hasSelection=Object.values(_paliersSelected).some(Boolean);
  if(!hasSelection){ all.forEach(function(u,i){_paliersSelected[u.n]=i<8;}); }
  else { all.forEach(function(u){ if(_paliersSelected[u.n]===undefined) _paliersSelected[u.n]=false; }); }
  return all.filter(function(u){return _paliersSelected[u.n];});
}
function renderPaliersPicker(){
  var list=$i('paliers-picker-list');if(!list)return;
  if(!_paliersSelected)_paliersSelected={};
  var cnt=Object.values(_paliersSelected).filter(Boolean).length;
  list.innerHTML=state.u.map(function(u){
    var on=!!_paliersSelected[u.n];var dis=!on&&cnt>=8;
    var sn=u.n.replace(/"/g,'&quot;');
    return '<label style="display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--b1);cursor:'+(dis?'not-allowed':'pointer')+';opacity:'+(dis?'.45':'1')+';">'
      +'<input type="checkbox" '+(on?'checked':'')+' '+(dis&&!on?'disabled':'')+' data-nom="'+sn+'" onchange="togglePaliersTeam(this)" style="accent-color:'+(u.color||'#4d84ff')+';width:15px;height:15px;flex-shrink:0;">'
      +'<span style="font-size:12px;font-weight:600;flex:1;">'+u.n+'</span>'
      +(on?'<span style="font-size:9px;color:'+(u.color||'#4d84ff')+';font-weight:700;">✓</span>':'')+'</label>';
  }).join('');
  var btn=$i('paliers-picker-btn');if(btn)btn.textContent='⚙️ '+cnt+'/8';
}
window.renderPaliersPicker=renderPaliersPicker;
function togglePaliersTeam(el){
  var nom=el.dataset.nom;var checked=el.checked;
  if(!_paliersSelected)_paliersSelected={};
  var cnt=Object.values(_paliersSelected).filter(Boolean).length;
  if(checked&&cnt>=8){el.checked=false;renderPaliersPicker();return;}
  _paliersSelected[nom]=checked;renderPaliersPicker();renderPaliersChart();
}
window.togglePaliersTeam=togglePaliersTeam;
function renderPaliersChart(){
  var ctx=$i('chart-paliers');if(!ctx)return;
  if(GC2.paliers){try{GC2.paliers.destroy();}catch(e){}}
  if(!state.u.length){ctx.parentElement.innerHTML='<div class="empty">Aucune équipe</div>';return;}
  var uList=_paliersEquipesActives();
  try{renderPaliersPicker();}catch(e){}
  if(!uList.length){ctx.parentElement.innerHTML='<div class="empty">Aucune équipe sélectionnée — clique sur ⚙️.</div>';return;}
  var labels=uList.map(function(u){return u.n;});   // nom complet (01/09, retour d'Antoine : 'Internaz' tronque trop court)
  var domData=[], extData=[], globData=[];
  uList.forEach(function(u){
    var dom=null, ext=null, glob=null;
    if(u.lc){
      Object.keys(u.lc).forEach(function(k){
        if(/\|dom$/.test(k)) dom=parseInt(u.lc[k],10)||1;
        else if(/\|ext$/.test(k)) ext=parseInt(u.lc[k],10)||1;
        else if(k.indexOf('|')<0) glob=parseInt(u.lc[k],10)||1;
      });
    }
    if(dom===null&&ext===null&&glob===null) glob=parseInt(u.l,10)||1;  // jamais engagee sur aucun lieu : repli
    domData.push(dom); extData.push(ext); globData.push(glob);
  });
  /* RETOUR EN VERTICAL (01/09, retour d'Antoine apres comparaison des deux
     maquettes) : conteneur a largeur fixe qui defile horizontalement plutot
     qu'une hauteur qui grandit avec le nombre d'equipes — chaque equipe garde
     une largeur minimale (46px) pour que les noms tournes restent lisibles. */
  var _hCont=ctx.parentElement;
  if(_hCont){ _hCont.style.height='280px'; _hCont.parentElement.style.overflowX='auto'; ctx.style.minWidth=Math.max(340, uList.length*46)+'px'; }
  var _logoImgs={};
  var _preloads=uList.map(function(u){
    return new Promise(function(resolve){
      var url=(typeof g45LogoUrlDe==='function')?g45LogoUrlDe(u.n):'';
      if(!url){ resolve(); return; }
      var img=new Image();
      img.crossOrigin='anonymous';
      img.onload=function(){ _logoImgs[u.n]=img; resolve(); };
      img.onerror=function(){ resolve(); };
      img.src=url;
    });
  });
  Promise.all(_preloads).then(function(){
    if(GC2.paliers){try{GC2.paliers.destroy();}catch(e){}}   // un autre appel a pu passer pendant le prechargement
    if(!$i('chart-paliers')) return;
    var _logoPlugin={
      id:'g45TeamLogos',
      afterFit:function(chart){ chart.scales.x.height=72; },
      afterDraw:function(chart){
        var xA=chart.scales.x, c=chart.ctx, area=chart.chartArea;
        c.save();
        c.strokeStyle='rgba(255,255,255,.85)'; c.lineWidth=2;
        for(var i=0;i<uList.length-1;i++){
          var mid=(xA.getPixelForTick(i)+xA.getPixelForTick(i+1))/2;
          c.beginPath(); c.moveTo(mid, area.top); c.lineTo(mid, area.bottom); c.stroke();
        }
        uList.forEach(function(u,i){
          var xPix=xA.getPixelForTick(i);
          var img=_logoImgs[u.n];
          if(img){ try{ c.drawImage(img, xPix-9, area.bottom+6, 18, 18); }catch(e){} }
          else {
            /* BADGE DE REPLI (01/09, retour d'Antoine : "sans logo en +" —
               les equipes sans logo n'avaient plus AUCUN repere visuel une
               fois le texte tronque retire). Pastille coloree avec
               l'initiale, meme esprit que le badge deja utilise ailleurs
               dans l'app pour un bookmaker sans favicon. */
            c.fillStyle=u.color||'#4d84ff';
            c.beginPath(); c.arc(xPix, area.bottom+15, 9, 0, Math.PI*2); c.fill();
            c.fillStyle='#fff'; c.font='bold 9px sans-serif'; c.textAlign='center'; c.textBaseline='middle';
            c.fillText((u.n||'?').charAt(0).toUpperCase(), xPix, area.bottom+15);
          }
          c.save();
          c.translate(xPix, area.bottom+(img?28:10));
          c.rotate(-Math.PI/4);
          c.fillStyle='#e8ecfa'; c.font='9px sans-serif'; c.textBaseline='middle'; c.textAlign='right';
          c.fillText(labels[i], 0, 0);
          c.restore();
        });
        c.restore();
      }
    };
    GC2.paliers=new Chart($i('chart-paliers').getContext('2d'),{
      type:'bar',
      data:{labels:labels,datasets:[
        {label:'🏠 Domicile',data:domData,backgroundColor:'rgba(30,215,96,.75)',borderColor:'rgba(30,215,96,1)',borderWidth:1,borderRadius:4},
        {label:'✈️ Extérieur',data:extData,backgroundColor:'rgba(77,132,255,.75)',borderColor:'rgba(77,132,255,1)',borderWidth:1,borderRadius:4},
        {label:'🌍 Global',data:globData,backgroundColor:'rgba(240,176,32,.75)',borderColor:'rgba(240,176,32,1)',borderWidth:1,borderRadius:4}
      ]},
      plugins:[_logoPlugin],
      options:{
        responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:true,labels:{color:'#8b97c4',font:{size:9},boxWidth:10}},tooltip:{callbacks:{label:function(i){return i.raw!=null?(i.dataset.label+' : Palier '+i.raw):null;}}}},
        scales:{
          x:{ticks:{display:false},grid:{display:false}},
          y:{min:0,max:8,ticks:{color:'#e8ecfa',font:{size:9},stepSize:1},grid:{color:'rgba(255,255,255,.03)'}}
        }
      }
    });
  });
}

function renderRadarChart(){
  var ctx=$i('chart-radar');if(!ctx)return;
  if(GC2.radar){try{GC2.radar.destroy();}catch(e){}}
  if(!state.a.length){ctx.parentElement.innerHTML='<div class="empty">Aucun historique</div>';return;}
  var typeMap={};
  state.a.forEach(function(h){
    var t=_normType(h.type);
    if(!typeMap[t])typeMap[t]={n:0,wins:0,profit:0,mise:0};
    typeMap[t].n++;
    if(h.win)typeMap[t].wins++;
    typeMap[t].profit+=(h.win?(h.m*h.cote)-h.m:-h.m);
    typeMap[t].mise+=parseFloat(h.m||0);
  });
  var entries=Object.entries(typeMap).sort(function(a,b){return b[1].n-a[1].n;}).slice(0,8);
  var labels=entries.map(function(e){return e[0];});
  var wrData=entries.map(function(e){return parseFloat((e[1].wins/e[1].n*100).toFixed(1));});
  var roiData=entries.map(function(e){return e[1].mise>0?parseFloat((e[1].profit/e[1].mise*100).toFixed(1)):0;});
  GC2.radar=new Chart(ctx.getContext('2d'),{
    type:'radar',
    data:{
      labels:labels,
      datasets:[
        {label:'Réussite %',data:wrData,borderColor:'rgba(30,215,96,.9)',backgroundColor:'rgba(30,215,96,.08)',borderWidth:2,pointBackgroundColor:'#1ed760',pointRadius:3},
        {label:'ROI %',data:roiData,borderColor:'rgba(77,132,255,.9)',backgroundColor:'rgba(77,132,255,.06)',borderWidth:2,pointBackgroundColor:'#4d84ff',pointRadius:3}
      ]
    },
    options:{
      responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:true,labels:{color:'#8b97c4',font:{size:10},boxWidth:10}}},
      scales:{r:{ticks:{color:'#e8ecfa',font:{size:9},backdropColor:'transparent'},grid:{color:'rgba(255,255,255,.07)'},pointLabels:{color:'#8b97c4',font:{size:9}}}}
    }
  });
}

/* ── MYMATCH ── */
var mmRows=[
  {type:'Victoire',cote:1.80},
  {type:'BTS Oui',cote:1.70}
];
var MM_TYPES=['Victoire','Nul','Défaite','Domicile ou nul','Extérieur ou nul','BTS Oui','BTS Non','Over 1.5','Over 2.5','Under 2.5','HC -1','HC +1','Mi-temps','Buteur','Passeur','Décisif'];

function renderMmRows(){
  var sel=$i('mm-sel');if(!sel)return;
  sel.innerHTML=mmRows.map(function(r,i){
    return '<div class="mm-row">'
      +'<input class="fi mm-cote" value="'+r.type+'" placeholder="Type (Victoire…)" data-idx="'+i+'" oninput="mmRows[this.dataset.idx].type=this.value;renderMmCote();" style="flex:1;padding:6px 8px;font-size:12px;">'
      +'<input type="text" inputmode="decimal" class="fi mm-cote" value="'+r.cote+'" data-idx="'+i+'" oninput="mmRows[this.dataset.idx].cote=parseFloat(this.value.replace(\',\',\'.\'))||1;renderMmCote();" style="width:72px;color:var(--a);font-weight:700;">'
      +(mmRows.length>1?'<button class="mm-del" data-idx="'+i+'" onclick="mmRows.splice(parseInt(this.dataset.idx),1);renderMmRows();">✕</button>':'')
      +'</div>';
  }).join('');
  var types=$i('mm-types');
  if(types)types.innerHTML=MM_TYPES.map(function(t){
    return '<button class="mm-type" onclick="addMmType(\''+t+'\')">'+ t+'</button>';
  }).join('');
  renderMmCote();
}
/* ═══ COTE COMBINEE MODIFIABLE (26/08) ═══
   Le cockpit n'affichait que le PRODUIT des selections. Or un bookmaker
   arrondit ou applique un boost : la cote enregistree n'etait donc pas celle du
   ticket, et le gain calcule etait faux.
   Le champ manuel prime quand il est rempli ; vide, on revient au calcul
   automatique. Le produit reste affiche, pour garder le point de comparaison
   sous les yeux. */
function _mmCoteManuelle(){
  var e=$i('mm-cote-manuelle');
  var v=e?(parseFloat(e.value)||0):0;
  return v>0?v:0;
}

function renderMmCote(){
  var cote=mmRows.reduce(function(a,r){return a*(parseFloat(r.cote)||1);},1);
  var el=$i('mm-cote-total');
  if(el)el.innerText='@'+cote.toFixed(2);
  /* C'est la cote EFFECTIVE qui part vers le champ du pari. */
  var eff=_mmCoteManuelle()||cote;
  var cc=$i('c-cote');if(cc)cc.value=eff.toFixed(2);
  /* Reperage visuel : le produit passe en gris barre des qu'une cote manuelle
     le remplace, pour qu'on voie laquelle sera reellement enregistree. */
  if(el){
    var manuel=_mmCoteManuelle()>0;
    el.style.opacity = manuel?'.42':'1';
    el.style.textDecoration = manuel?'line-through':'none';
  }
  renderCrash();
}
window.mmCoteManuelle=function(){ try{ renderMmCote(); }catch(e){} };
function addMmRow(){mmRows.push({type:'',cote:1.50});renderMmRows();}
function addMmType(t){
  var existing=mmRows.find(function(r){return r.type===t;});
  if(existing)return;
  mmRows.push({type:t,cote:1.50});renderMmRows();
}

// ── ENREGISTRER MYMATCH COMME PARI ──

function setLieu(v) {
  var inp = document.getElementById('n-lieu');
  if(inp) inp.value = v;
  var btns = {'dom':'btn-dom','ext':'btn-ext','':'btn-neut'};
  Object.keys(btns).forEach(function(k){
    var b = document.getElementById(btns[k]);
    if(!b) return;
    if(k===v){
      b.style.borderColor='rgba(30,215,96,.5)';b.style.background='rgba(30,215,96,.12)';b.style.color='#1ed760';
    } else {
      b.style.borderColor='var(--b2)';b.style.background='none';b.style.color='var(--t3)';
    }
  });
}

function saveMmAsPari(mode) {
  var rows = mode === 'cockpit' ? mmRows : mmRowsSimple;
  if (!rows || !rows.length || !rows.some(function(r){ return r.type; })) {
    alert('Ajoute au moins une sélection !'); return;
  }
  var coteProduit = rows.reduce(function(a,r){ return a*(parseFloat(r.cote)||1); }, 1);
  /* COTE MANUELLE PRISE EN COMPTE A L'ENREGISTREMENT (27/08). `renderMmCote()`
     affichait deja la cote manuelle en aperçu (barre le produit automatique),
     mais `saveMmAsPari` recalculait le produit brut depuis `rows` sans jamais
     regarder le champ manuel : le pari enregistrait toujours le produit, pas
     la cote reelle du ticket. Seul le mode 'cockpit' a ce champ. */
  var cote = (mode==='cockpit' && typeof _mmCoteManuelle==='function' && _mmCoteManuelle()>0) ? _mmCoteManuelle() : coteProduit;
  /* COTE RETIREE DU LIBELLE (25/08). Elle etait collee a chaque selection —
     « Victoire @1.8 + BTS Oui @1.7 » — ce qui faisait de chaque combinaison de
     cotes un TYPE distinct : le bilan comptait autant de categories que de
     paris. Le nettoyage a la lecture ne suffisait pas, le formulaire d'edition
     affichant la valeur brute. On corrige donc a la SOURCE.
     La cote totale reste enregistree dans le champ `cote` du pari. */
  var label = rows.filter(function(r){ return r.type; }).map(function(r){ return r.type; }).join(' + ');

  // Récupérer les infos selon le mode
  var team, mise, book, date, sport, comp;
  if (mode === 'cockpit') {
    team = ($i('c-unit') && $i('c-unit').value) || 'MyMatch';
    mise = parseFloat($i('c-mise') && $i('c-mise').value) || 0;
    book = ($i('c-book') && $i('c-book').value) || '';
    date = ($i('c-date') && $i('c-date').value) || new Date().toISOString().split('T')[0];
    sport = ($i('c-sport') && $i('c-sport').value) || '⚽';
    comp = ($i('c-comp') && $i('c-comp').value) || '';
  } else {
    team = ($i('n-team') && $i('n-team').value) || 'MyMatch';
    mise = parseFloat($i('n-mise') && $i('n-mise').value) || 0;
    book = ($i('n-book') && $i('n-book').value) || '';
    date = ($i('n-date') && $i('n-date').value) || new Date().toISOString().split('T')[0];
    sport = ($i('p-sport') && $i('p-sport').value) || '⚽';
    comp = ($i('n-comp') && $i('n-comp').value) || '';
  }

  if (!mise) { alert('Renseigne une mise !'); return; }

  // Créer le pari dans l'archive comme un pari en attente
  var pari = {
    id: Date.now(),
    n: team || 'Combiné',
    cote: parseFloat(cote.toFixed(2)),
    m: mise,
    book: book,
    date: date,
    sport: sport,
    comp: comp,
    type: label,
    mm: true,  // marqué comme MyMatch
    win: null, // en attente de résultat
    r: null
  };

  if (!state.p) state.p = [];
  state.p.push(pari);
  save();

  // Feedback visuel
  var btn = event && event.target;
  if (btn) {
    btn.textContent = '✓ Enregistré !';
    btn.style.borderColor = 'rgba(30,215,96,.8)';
    btn.style.background = 'rgba(30,215,96,.2)';
    setTimeout(function(){ btn.textContent = '💾 Enregistrer pari'; btn.style.borderColor='rgba(30,215,96,.4)'; btn.style.background='rgba(30,215,96,.1)'; }, 2000);
  }

  render();
}

function getMmLabel(){
  return mmRows.filter(function(r){return r.type;}).map(function(r){return r.type;}).join(' + ');
}
function getMmCote(){
  /* COTE MANUELLE PRISE EN COMPTE ICI AUSSI (27/08, 2e endroit trouve apres
     retour d'Antoine). `getMmCote()` est ce que lit `pari(true)` pour la
     colonne "Engager la montante" — un chemin totalement distinct de
     `saveMmAsPari` (le bouton "Enregistrer pari" du cockpit), corrige plus
     tot. Meme bug ici : le produit brut de `mmRows` etait renvoye sans jamais
     regarder le champ "cote reelle" manuel. */
  var produit=mmRows.reduce(function(a,r){return a*(parseFloat(r.cote)||1);},1);
  return (typeof _mmCoteManuelle==='function' && _mmCoteManuelle()>0) ? _mmCoteManuelle() : produit;
}

/* ── SEARCH CLUB API-SPORTS ── */
var _searchTimer=null;
function debounceSearchClub(){
  clearTimeout(_searchTimer);
  _searchTimer=setTimeout(searchClub,600);
}
function searchClub(){
  var q=($i('u-search')&&$i('u-search').value||'').trim();
  var res=$i('search-results');if(!res)return;
  if(q.length<2){res.innerHTML='';window._srCache=[];return;}
  res.innerHTML='<div class="search-loading">🔍 Recherche...</div>';
  window._srCache=fuzzyClubSearch(q);
  if(window._srCache.length){
    res.innerHTML='<div class="search-res">'+window._srCache.map(function(r,i){
      return '<div class="sr-item" data-idx="'+i+'" onclick="selectClub(+this.dataset.idx)">'
        +'<img class="sr-logo" src="'+r.logo+'" onerror="logoErr(this)" loading="lazy">'
        +'<div><div class="sr-name">'+r.name+'</div>'
        +'<div class="sr-meta">'+r.league+' · '+'&#9733;'.repeat(r.stars||3)+'</div></div>'
        +'<span style="font-size:11px;color:var(--a);font-weight:700;">&#8629;</span>'
        +'</div>';
    }).join('')+'</div>';
  } else {
    res.innerHTML='<div class="search-res"><div class="sr-item" style="cursor:default;color:var(--t3);">Aucun résultat</div></div>';
  }
}
function selectClub(idx){
  var r=(window._srCache||[])[idx];if(!r)return;
  if($i('u-name'))$i('u-name').value=r.name;
  if($i('u-note'))$i('u-note').value=r.note||'';
  if($i('u-stars'))$i('u-stars').value=String(r.stars||3);
  if(r.color){if($i('u-color'))$i('u-color').value=r.color;selColor=r.color;renderColorPicker();}
  window._pendingLogo={name:r.name,url:r.logo,abbr:r.abbr||r.name.substring(0,3).toUpperCase(),color:r.color||PCOLS[0]};
  if($i('u-link2')&&r.flashscore)$i('u-link2').value=r.flashscore;
  if($i('u-link')&&r.sofascore)$i('u-link').value=r.sofascore;
  var res=$i('search-results');
  if(res)res.innerHTML='<div style="color:var(--g);font-size:11px;font-weight:700;padding:8px 0;">✅ '+r.name+' sélectionné — clique sur Ajouter</div>';
}
