function getFdorgKey(){ return localStorage.getItem('gones45_fdorg_key')||null; }
/* ═══ MODÈLE GROQ — DÉCOUVERTE AUTOMATIQUE (15/08/2026) ═══
   `llama-3.3-70b-versatile` a ete retire par Groq du jour au lendemain, et les
   15 appels de l'appli le nommaient EN DUR. Le remplacer par un autre nom fixe
   ne ferait que repousser le probleme : Groq renouvelle son catalogue plusieurs
   fois par an.
   On interroge donc /openai/v1/models — gratuit, ne consomme aucun jeton — et on
   prend le premier modele de la liste de preference REELLEMENT disponible.
   Cache 24 h, et repli sur un nom connu si l'appel echoue. */
var G45_GROQ_PREF = [
  'llama-3.3-70b-versatile',
  'meta-llama/llama-4-maverick-17b-128e-instruct',
  'meta-llama/llama-4-scout-17b-16e-instruct',
  'openai/gpt-oss-120b',
  'moonshotai/kimi-k2-instruct',
  'qwen/qwen3-32b',
  'openai/gpt-oss-20b',
  'llama-3.1-8b-instant'
];
var G45_GROQ_MODELE = null;

/* ═══ MODÈLES GEMINI — MÊME MALADIE, MÊME REMÈDE ═══
   `gemini-1.5-flash` a ete retire par Google. La cascade nommait ses quatre
   modeles en dur : chaque retrait cassera donc un maillon, en silence, jusqu'a
   ce qu'il n'en reste aucun.
   L'endpoint /v1beta/models liste ce que LA CLE peut reellement appeler. On ne
   garde que les modeles qui acceptent `generateContent`, tries du plus recent
   au plus ancien, en ecartant les modeles d'image et d'embedding. */
var G45_GEM_LISTE = null;

async function g45GeminiModeles(force) {
  if (G45_GEM_LISTE && !force) return G45_GEM_LISTE;
  var repli = ['gemini-2.5-flash', 'gemini-2.0-flash', 'gemini-2.0-flash-lite'];
  try {
    if (!force) {
      var o = JSON.parse(localStorage.getItem('g45_gem_modeles') || 'null');
      if (o && o.l && o.l.length && (Date.now() - o.t) < 86400000) { G45_GEM_LISTE = o.l; return o.l; }
    }
  } catch (e) {}

  var cle = localStorage.getItem('gones45_google_key');
  if (!cle) return repli;
  try {
    var r = await fetch('https://generativelanguage.googleapis.com/v1beta/models?key=' + encodeURIComponent(cle));
    if (!r.ok) throw new Error('HTTP ' + r.status);
    var j = await r.json();
    var ok = ((j && j.models) || []).filter(function (m) {
      var meth = m.supportedGenerationMethods || m.supportedActions || [];
      return meth.indexOf('generateContent') >= 0 && !/embed|image|vision-only|aqa/i.test(m.name || '');
    }).map(function (m) { return String(m.name || '').replace(/^models\//, ''); });

    /* On prefere les « flash » : gratuits et rapides, ce qui compte pour une
       analyse d'avant-match. Puis tri decroissant, donc les versions recentes
       d'abord. */
    var flash = ok.filter(function (n) { return /flash/i.test(n); }).sort().reverse();
    var autres = ok.filter(function (n) { return !/flash/i.test(n); }).sort().reverse();
    var liste = flash.concat(autres).slice(0, 6);
    if (liste.length) {
      G45_GEM_LISTE = liste;
      try { localStorage.setItem('g45_gem_modeles', JSON.stringify({ l: liste, t: Date.now() })); } catch (e) {}
      console.log('\ud83d\udd37 mod\u00e8les Gemini disponibles : ' + liste.join(', '));
      return liste;
    }
  } catch (e) { console.warn('decouverte Gemini', e && e.message); }
  return repli;
}
window.g45GeminiModeles = g45GeminiModeles;

function g45GroqModele() {
  if (G45_GROQ_MODELE) return G45_GROQ_MODELE;
  try {
    var o = JSON.parse(localStorage.getItem('g45_groq_modele') || 'null');
    if (o && o.m && (Date.now() - o.t) < 86400000) { G45_GROQ_MODELE = o.m; return o.m; }
  } catch (e) {}
  return G45_GROQ_PREF[0];          /* repli le temps que la decouverte reponde */
}
window.g45GroqModele = g45GroqModele;

async function g45GroqDecouvrir(force) {
  var cle = localStorage.getItem('gones45_gemini_key');   /* clé Groq, nom historique */
  if (!cle) return g45GroqModele();
  if (!force) {
    try {
      var o = JSON.parse(localStorage.getItem('g45_groq_modele') || 'null');
      if (o && o.m && (Date.now() - o.t) < 86400000) { G45_GROQ_MODELE = o.m; return o.m; }
    } catch (e) {}
  }
  try {
    var r = await fetch('https://api.groq.com/openai/v1/models', { headers: { 'Authorization': 'Bearer ' + cle } });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    var j = await r.json();
    var dispo = ((j && j.data) || []).map(function (x) { return x.id; });
    var choisi = G45_GROQ_PREF.filter(function (m) { return dispo.indexOf(m) >= 0; })[0];
    /* Aucune preference disponible : on prend le plus gros modele texte propose,
       plutot que d'echouer. */
    if (!choisi) choisi = dispo.filter(function (m) { return !/whisper|tts|guard|embed/i.test(m); })[0];
    if (choisi) {
      G45_GROQ_MODELE = choisi;
      try { localStorage.setItem('g45_groq_modele', JSON.stringify({ m: choisi, t: Date.now() })); } catch (e) {}
      console.log('\ud83e\udde0 mod\u00e8le Groq retenu : ' + choisi + ' (' + dispo.length + ' disponibles)');
    }
  } catch (e) { console.warn('decouverte Groq', e && e.message); }
  return g45GroqModele();
}
window.g45GroqDecouvrir = g45GroqDecouvrir;

var FD_PROXY = 'https://fd-proxy.touraine-antoine.workers.dev';

// Cache mémoire + file d'attente anti-rate-limit pour football-data (plan free: 10 req/min)
var _fdCache = {};
var _fdQueue = Promise.resolve();
var _fdLastCall = 0;
var _FD_MIN_GAP = 6500; // ms entre 2 appels (≈9/min, sous la limite de 10/min)

async function fdFetch(path) {
  var key = getFdorgKey();
  if(!key) return null;

  // Cache : même chemin → réponse mémorisée (10 min)
  var ck = path;
  var now = Date.now();
  if(_fdCache[ck] && (now - _fdCache[ck].ts < 600000)) {
    return _fdCache[ck].data;
  }

  // Sérialiser les appels avec un délai minimum entre chacun
  var run = _fdQueue.then(async function(){
    var gap = Date.now() - _fdLastCall;
    if(gap < _FD_MIN_GAP) await new Promise(function(res){ setTimeout(res, _FD_MIN_GAP - gap); });

    for(var attempt=0; attempt<3; attempt++){
      try {
        var r = await fetch(FD_PROXY+'?key='+encodeURIComponent(key)+'&path='+encodeURIComponent(path));
        _fdLastCall = Date.now();
        if(r.status===429 || r.status===403){
          // Rate limit → attendre et réessayer
          await new Promise(function(res){ setTimeout(res, 8000); });
          continue;
        }
        if(!r.ok) return null;
        var data = await r.json();
        _fdCache[ck] = {ts:Date.now(), data:data};
        return data;
      } catch(e) {
        await new Promise(function(res){ setTimeout(res, 1500); });
      }
    }
    return null;
  });
  _fdQueue = run.catch(function(){});
  return run;
}

