function pal(hex){
  var r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  return{bg:'rgba('+r+','+g+','+b+',.08)',badge:'rgba('+r+','+g+','+b+',.14)',border:'rgba('+r+','+g+','+b+',.28)',c:hex,fade:'rgba('+r+','+g+','+b+',.12)'};
}
