        html += '<div onclick="_callUS(\''+cKey+'\')" style="flex:1;text-align:center;background:var(--s1);border-radius:10px;padding:7px 3px;border-top:3px solid '+col+';border:1px solid rgba(255,255,255,.06);cursor:pointer;">';
