        var aName=g.awayTeam&&(g.awayTeam.name&&g.awayTeam.name.default||g.awayTeam.abbrev)||'?';
        var won=ts>os, draw=ts===os;
        var rc=won?'#1ed760':draw?'#f0b020':'#ff4545';
