var _g45NatByAlias=(function(){var m={};G45_NATIONS.forEach(function(n){m[_g45norm(n.fr)]=n;(n.a||[]).forEach(function(a){m[_g45norm(a)]=n;});});return m;})();
function _g45NationId(nom){var n=_g45NatByAlias[_g45norm(nom)];return n?n.id:null;}
var _G45_INTL_RE=/coupe du monde|mondial|world cup|fifa|euro|nations|qualif|amical|copa|afcon|\bcan\b/;
/* Pêche TOUTES les nations citées dans un texte de pari international (n + target), même mal orthographiées/sans accents */
function _g45HarvestNations(text,comp,addFn){
  var hay=_g45norm((text||'')+' '+(comp||''));
  if(!_G45_INTL_RE.test(hay)) return;
  var nt=_g45norm(text);
  G45_NATIONS.forEach(function(n){
    var keys=[_g45norm(n.fr)].concat((n.a||[]).map(_g45norm));
    for(var i=0;i<keys.length;i++){ var k=keys[i]; if(!k||k.length<3) continue;
      var re=new RegExp('(^|[^a-z0-9])'+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z0-9]|$)');
      if(re.test(nt)){ addFn(n.fr,'\u26bd',comp); break; }
    }
  });
}
async function _g45ResolveTeam(nom){
  var _nid=_g45NationId(nom); if(_nid) return {id:_nid, league:'fifa.world'};
  try{ var r=await espnResolveTeam(nom); if(r&&r.id) return {id:String(r.id), league:r.league||''}; }catch(e){}
  if(typeof _espnLoadLeagueTeams==='function' && typeof _espnMatchTeam==='function'){
    try{ var wt=await _espnLoadLeagueTeams('fifa.world'); var m=_espnMatchTeam(nom,wt,'fifa.world','exact')||_espnMatchTeam(nom,wt,'fifa.world','partial'); if(m&&m.id) return {id:String(m.id), league:'fifa.world'}; }catch(e){}
  }
  return null;
}

async function g45SyncNotifs(subOpt){
  var reg=await navigator.serviceWorker.getRegistration();
  var sub=subOpt||(reg&&await reg.pushManager.getSubscription());
  if(!sub) return;
  var p=g45NotifPrefs();
  var favs=(typeof state!=='undefined'&&state.u?state.u:[]).filter(function(u){ return (u.sport||'\u26bd')==='\u26bd' && p.teams[u.n]; });
  var teams=[];
  for(var i=0;i<favs.length;i++){ var r=await _g45ResolveTeam(favs[i].n); if(r) teams.push({n:favs[i].n, id:r.id, league:r.league}); }
  var betTeams=[];
  if(p.bets!==false){ try{ betTeams=await g45BetTeams(); }catch(e){} } // Phase 2 : matchs des paris (foot + rugby), surveillés à part, taggés 🎯
  // Phase 3 : matchs suivis manuellement (⭐) → notifs sur cet event précis, hors favoris
  var suivis=[]; try{ suivis=g45SuivisGet().map(function(m){ return {id:String(m.id), sport:m.sport||'soccer', league:m.league||'', date:m.date||'', home:m.home||'', away:m.away||''}; }); }catch(e){}
  try{ await fetch(FD_PROXY+'/psub',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sub:sub,teams:teams,betTeams:betTeams,matches:suivis,ev:p.ev})}); }catch(e){}
}
/* Sélections (foot ⚽ + rugby 🏉) des paris en cours → {name, sport, comp} */
function g45BetSelections(){
  var seen={}, out=[];
  function add(name, sportEmoji, comp){
    if(!name) return; name=String(name).trim(); if(!name||name==='SIMPLE'||name==='-') return;
    var se=String(sportEmoji||''), cl=String(comp||'').toLowerCase();
    var sp = se.indexOf('\u26bd')>=0 ? 'soccer'
      : (se.indexOf('\ud83c\udfc9')>=0
          ? ((se.indexOf('\ud83c\udde6\ud83c\uddfa')>=0 || /\bnrl\b|rugby.?league|treize|xiii/.test(cl)) ? 'nrl' : 'rugby')
          : null);
    if(!sp) return;
    var k=sp+'|'+name.toLowerCase(); if(seen[k]) return; seen[k]=1;
    out.push({name:name, sport:sp, comp:comp||''});
  }
  function fromTarget(t, sp, comp){ if(!t) return; var m=String(t).split(/\s+vs\.?\s+/i); if(m.length>=2){ add(m[0],sp,comp); add(m[1],sp,comp); } }
  var H=(typeof state!=='undefined'&&state.h)?state.h:[];
  H.forEach(function(h){
    if(h.notif===false) return;
    if(h.isCombi){ (h.combiRows||[]).forEach(function(r){ add(r.team, r.sport||'\u26bd', r.comp||h.comp); add(r.adv, r.sport||'\u26bd', r.comp||h.comp); }); }
    else { var sp=h.sport||'\u26bd'; if(h.n && h.n!=='SIMPLE') add(h.n, sp, h.comp); fromTarget(h.target, sp, h.comp);
      if(String(sp).indexOf('\u26bd')>=0) _g45HarvestNations((h.n||'')+' '+(h.target||''), h.comp, add); }
  });
  return out;
}
var G45_RUGBY_LG = {'top 14':'270559','top14':'270559','champions cup':'271937','champions':'271937','challenge cup':'271938','challenge':'271938','urc':'270557','united rugby':'270557','premiership':'267979','six nations':'180659','rugby championship':'270563','super rugby':'242041'};
function _g45RugbyLeagueId(comp){ var c=String(comp||'').toLowerCase(); for(var k in G45_RUGBY_LG){ if(c.indexOf(k)>=0) return G45_RUGBY_LG[k]; } return '270559'; /* défaut Top 14 */ }
async function _g45ResolveEspnTeam(name, sportPath, league){
  if(!league) return null;
  var ck='g45esp_teams_'+sportPath+'_'+league, teams=null;
  try{ var c=localStorage.getItem(ck); if(c){ var o=JSON.parse(c); if(o&&o.ts&&(Date.now()-o.ts<7*864e5)) teams=o.list; } }catch(e){}
  if(!teams){
    try{
      var r=await fetch(FD_PROXY+'/?host=espn&path=/apis/site/v2/sports/'+sportPath+'/'+league+'/teams'); if(!r.ok) return null;
      var j=await r.json(); var s=j.sports||[]; var lst=((((s[0]||{}).leagues||[])[0]||{}).teams)||j.teams||[];
      teams=lst.map(function(t){ var tt=t.team||t; return {id:String(tt.id), n:String(tt.displayName||tt.name||'')}; });
      try{ localStorage.setItem(ck, JSON.stringify({ts:Date.now(), list:teams})); }catch(e){}
    }catch(e){ return null; }
  }
  var nm=String(name||'').toLowerCase().trim(); if(!nm) return null;
  var found=teams.find(function(t){ return t.n.toLowerCase()===nm; }) || teams.find(function(t){ var tn=t.n.toLowerCase(); return tn.indexOf(nm)>=0 || nm.indexOf(tn)>=0; });
  return found?{id:found.id, league:league}:null;
}
async function _g45ResolveRugbyTeam(name, comp){ return _g45ResolveEspnTeam(name, 'rugby', _g45RugbyLeagueId(comp)); }
async function g45BetTeams(){
  var sels=g45BetSelections(), out=[], seen={};
  for(var i=0;i<sels.length;i++){
    var s=sels[i], res=null;
    try{
      if(s.sport==='soccer') res=await _g45ResolveTeam(s.name);
      else if(s.sport==='rugby') res=await _g45ResolveEspnTeam(s.name, 'rugby', _g45RugbyLeagueId(s.comp));
      else if(s.sport==='nrl') res=await _g45ResolveEspnTeam(s.name, 'rugby-league', '3');
    }catch(e){}
    if(res && res.id){ var k=s.sport+'|'+res.league+'|'+res.id; if(seen[k]) continue; seen[k]=1; out.push({n:s.name, id:String(res.id), league:res.league, sport:s.sport}); }
  }
  return out;
}
/* Équipes (foot) des paris en cours (state.h) : simple, combiné, unité → noms à résoudre */
function g45BetTeamNames(){
  var seen={}, out=[];
  function add(nm){ if(!nm) return; nm=String(nm).trim(); if(!nm||nm==='SIMPLE'||nm==='-') return; var k=nm.toLowerCase(); if(seen[k]) return; seen[k]=1; out.push(nm); }
  function fromTarget(t){ if(!t) return; var m=String(t).split(/\s+vs\.?\s+/i); if(m.length>=2){ add(m[0]); add(m[1]); } }
  var H=(typeof state!=='undefined'&&state.h)?state.h:[];
  H.forEach(function(h){
    if(h.notif===false) return;
    if(h.isCombi){ (h.combiRows||[]).forEach(function(r){ if((r.sport||'\u26bd')==='\u26bd'){ add(r.team); add(r.adv); } }); }
    else if((h.sport||'\u26bd')==='\u26bd'){ if(h.n && h.n!=='SIMPLE') add(h.n); fromTarget(h.target); }
  });
  return out;
}
function toggleNotifBets(){ var p=g45NotifPrefs(); var cur=p.bets!==false; p.bets=!cur; g45NotifPrefsSave(p); renderNotifPanel(); if(p.enabled){ try{ g45SyncNotifs(); }catch(e){} } }

async function g45EnableNotifs(){
  _notifMsg('Activation\u2026','var(--t3)');
  try{
    var reg=await navigator.serviceWorker.register('sw.js');
    await navigator.serviceWorker.ready;
    var perm=await Notification.requestPermission();
    if(perm!=='granted'){ _notifMsg('Permission refus\u00e9e \u2014 autorise les notifications pour le site dans les r\u00e9glages du navigateur.','#ff6b6b'); return; }
    var sub=await reg.pushManager.getSubscription();
    if(!sub) sub=await reg.pushManager.subscribe({userVisibleOnly:true, applicationServerKey:_urlB64ToU8(G45_VAPID_PUBLIC)});
    var p=g45NotifPrefs(); p.enabled=true;
    var favs=(typeof state!=='undefined'&&state.u?state.u:[]).filter(function(u){ return (u.sport||'\u26bd')==='\u26bd'; });
    var anyTeam=false; for(var k in p.teams){ if(p.teams[k]){ anyTeam=true; break; } }
    if(!anyTeam) favs.forEach(function(u){ p.teams[u.n]=true; });
    g45NotifPrefsSave(p);
    renderNotifPanel();
    _notifMsg('Enregistrement des \u00e9quipes\u2026','var(--t3)');
    await g45SyncNotifs(sub);
    renderNotifPanel();
    _notifMsg('\u2705 Notifications activ\u00e9es !');
  }catch(e){ _notifMsg('Erreur : '+((e&&e.message)||e),'#ff6b6b'); }
}

async function g45DisableNotifs(){
  try{
    var reg=await navigator.serviceWorker.getRegistration();
    var sub=reg&&await reg.pushManager.getSubscription();
    if(sub){ try{ await fetch(FD_PROXY+'/punsub',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})}); }catch(e){} try{ await sub.unsubscribe(); }catch(e){} }
  }catch(e){}
  var p=g45NotifPrefs(); p.enabled=false; g45NotifPrefsSave(p);
  renderNotifPanel(); _notifMsg('Notifications d\u00e9sactiv\u00e9es.','var(--t3)');
}

function toggleNotifEvent(type){
  var p=g45NotifPrefs(); var on=(p.ev[type]!==false); p.ev[type]=!on; g45NotifPrefsSave(p);
  if(p.enabled) g45SyncNotifs();
  renderNotifPanel();
}
function toggleNotifTeam(nom){
  var p=g45NotifPrefs(); p.teams[nom]=!p.teams[nom]; g45NotifPrefsSave(p);
  renderNotifPanel();
  if(p.enabled){ _notifMsg('Mise \u00e0 jour\u2026','var(--t3)'); g45SyncNotifs().then(function(){ _notifMsg('\u2705 \u00c9quipes mises \u00e0 jour'); }); }
}

async function g45TestNotif(){
  try{
    var reg=await navigator.serviceWorker.getRegistration(); var sub=reg&&await reg.pushManager.getSubscription();
    if(!sub){ _notifMsg('Active d\'abord les notifications.','#ff6b6b'); return; }
    await fetch(FD_PROXY+'/ptest?ep='+encodeURIComponent(sub.endpoint));
    _notifMsg('Notif de test envoy\u00e9e \u2014 elle arrive dans quelques secondes \ud83d\udcf2');
  }catch(e){ _notifMsg('Erreur test : '+((e&&e.message)||e),'#ff6b6b'); }
}

