  try{
    if(typeof g45StatsForEvent==='function'){
      var ds=g45StatsForEvent({sport:'⚽',teams:[hN,aN],comp:comp,place:''});
      ds.slice(0,4).forEach(function(st){ facts.push('Note perso de l\'utilisateur: '+st.text); });
    }
  }catch(e){}
