function _g45RenderMoreOdds(ev, hN, aN, remain){
  function ea(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');}
  var bks=((ev&&ev.bookmakers)||[]).filter(function(b){ return !!_g45MyBook(b.key); }); // ← seulement TES books
  function bookShort(b){ return _g45MyBook(b.key)||b.title||b.key; }
  function booksWith(mk){ return bks.filter(function(b){ return (b.markets||[]).some(function(m){return m.key===mk;}); }); }
  function priceOf(b, mkeys, pred){ var best=null; (b.markets||[]).forEach(function(m){ if(mkeys.indexOf(m.key)<0)return; (m.outcomes||[]).forEach(function(o){ if(pred(o)){ if(best==null||o.price>best)best=o.price; } }); }); return best; }
  function cell(p,isB){ if(p==null) return '<td style="text-align:center;padding:5px 4px;color:var(--t3);">—</td>'; return '<td style="text-align:center;padding:5px 4px;font-weight:'+(isB?'800':'600')+';color:'+(isB?'#2ecc71':'var(--t1)')+';">'+p.toFixed(2)+'</td>'; }
  function bcell(b){ return '<td style="padding:5px 4px;font-size:11px;color:var(--t1);white-space:nowrap;">'+ea(bookShort(b))+'</td>'; }
  function mx(a){ var m=0; a.forEach(function(v){ if(v&&v>m)m=v; }); return m; }

  // ── O/U : un mini-tableau par ligne (1.5 / 2.5 / 3.5), façon 1X2 ──
  var ouMk=['alternate_totals','totals'];
  var ouBooks=booksWith('alternate_totals').concat(booksWith('totals')).filter(function(b,i,a){return a.indexOf(b)===i;});
  var ouBlock='';
  if(ouBooks.length){
    ouBlock+='<div style="font-size:10px;font-weight:800;color:#4d84ff;margin:2px 0 4px;">⚽ TOTAL DE BUTS</div>';
    [1.5,2.5,3.5].forEach(function(p){
      var rows=ouBooks.map(function(b){ return {b:b, ov:priceOf(b,ouMk,function(o){return o.name==='Over'&&Math.abs((o.point||0)-p)<0.001;}), un:priceOf(b,ouMk,function(o){return o.name==='Under'&&Math.abs((o.point||0)-p)<0.001;})}; }).filter(function(r){return r.ov!=null||r.un!=null;});
      if(!rows.length) return;
      var bO=mx(rows.map(function(r){return r.ov;})), bU=mx(rows.map(function(r){return r.un;}));
      var body=rows.map(function(r){ return '<tr>'+bcell(r.b)+cell(r.ov,r.ov&&r.ov===bO)+cell(r.un,r.un&&r.un===bU)+'</tr>'; }).join('');
      ouBlock+='<div style="font-size:9px;color:var(--t3);margin:7px 0 2px;font-weight:700;">Plus / Moins de '+p+' buts</div>'
        +'<table style="width:100%;border-collapse:collapse;"><tr style="font-size:9px;color:var(--t3);text-transform:uppercase;"><th style="text-align:left;padding:3px 4px;">Book</th><th style="padding:3px 4px;">+ Over</th><th style="padding:3px 4px;">− Under</th></tr>'+body+'</table>';
    });
  }

  // ── BTTS : tableau lignes=books, colonnes Oui/Non ──
  var bttsBooks=booksWith('btts');
  var bttsBlock='';
  if(bttsBooks.length){
    var rb=bttsBooks.map(function(b){ return {b:b, y:priceOf(b,['btts'],function(o){return /^y|oui/i.test(o.name);}), n:priceOf(b,['btts'],function(o){return /^n|non/i.test(o.name);})}; });
    var bY=mx(rb.map(function(r){return r.y;})), bN=mx(rb.map(function(r){return r.n;}));
    var body=rb.map(function(r){ return '<tr>'+bcell(r.b)+cell(r.y,r.y&&r.y===bY)+cell(r.n,r.n&&r.n===bN)+'</tr>'; }).join('');
    bttsBlock='<div style="font-size:10px;font-weight:800;color:#4d84ff;margin:10px 0 4px;">🥅 LES DEUX ÉQUIPES MARQUENT</div>'
      +'<table style="width:100%;border-collapse:collapse;"><tr style="font-size:9px;color:var(--t3);text-transform:uppercase;"><th style="text-align:left;padding:3px 4px;">Book</th><th style="padding:3px 4px;">Oui</th><th style="padding:3px 4px;">Non</th></tr>'+body+'</table>';
  }

  // ── BUTEUR : lignes=joueurs (top 15), colonnes=books ──
  var scBooks=booksWith('player_goal_scorer_anytime');
  var scBlock='';
  if(scBooks.length){
    var players={};
    scBooks.forEach(function(b){ (b.markets||[]).forEach(function(m){ if(m.key!=='player_goal_scorer_anytime')return; (m.outcomes||[]).forEach(function(o){ var nm=o.description; if(!nm)return; if(!players[nm])players[nm]={}; if(!players[nm][b.key])players[nm][b.key]={y:null,n:null}; if(/^y|oui/i.test(o.name)){ if(players[nm][b.key].y==null||o.price>players[nm][b.key].y)players[nm][b.key].y=o.price; } else if(/^n|non/i.test(o.name)){ if(players[nm][b.key].n==null||o.price>players[nm][b.key].n)players[nm][b.key].n=o.price; } }); }); });
    var anyNo=Object.keys(players).some(function(nm){ return scBooks.some(function(b){ return players[nm][b.key]&&players[nm][b.key].n!=null; }); });
    var arr=Object.keys(players).map(function(nm){ var ys=scBooks.map(function(b){return players[nm][b.key]?players[nm][b.key].y:null;}).filter(function(x){return x!=null;}); return {nm:nm, fav:(ys.length?Math.min.apply(null,ys):999)}; }).filter(function(x){return x.fav<999;}).sort(function(a,b){return a.fav-b.fav;}).slice(0,15);
    var head='<tr style="font-size:9px;color:var(--t3);text-transform:uppercase;"><th style="text-align:left;padding:3px 4px;">Joueur</th>'+scBooks.map(function(b){ return '<th style="padding:3px 4px;">'+ea(bookShort(b))+(anyNo?' Oui':'')+'</th>'+(anyNo?'<th style="padding:3px 4px;color:#ff9f3c;">Non</th>':''); }).join('')+'</tr>';
    var body=arr.map(function(x){ var rowBest=mx(scBooks.map(function(b){return players[x.nm][b.key]?players[x.nm][b.key].y:null;}));
      return '<tr><td style="padding:4px;font-size:11px;color:var(--t1);">'+ea(x.nm)+'</td>'+scBooks.map(function(b){ var pd=players[x.nm][b.key]||{}; var c=cell(pd.y, pd.y&&pd.y===rowBest); if(anyNo){ c+=(pd.n!=null?'<td style="text-align:center;padding:5px 4px;font-weight:600;color:#ff9f3c;">'+pd.n.toFixed(2)+'</td>':'<td style="text-align:center;padding:5px 4px;color:var(--t3);">—</td>'); } return c; }).join('')+'</tr>'; }).join('');
    scBlock='<div style="font-size:10px;font-weight:800;color:#4d84ff;margin:10px 0 4px;">👟 BUTEUR À TOUT MOMENT'+(anyNo?' <span style="font-weight:600;color:var(--t3);">(Oui = marque · Non = ne marque pas)</span>':'')+'</div>'
      +'<table style="width:100%;border-collapse:collapse;">'+head+body+'</table>';
  }

  var inner = ouBlock+bttsBlock+scBlock;
  if(!inner) inner='<div style="color:var(--t3);font-size:11px;padding:6px;">Aucun de tes books ne propose ces marchés sur ce match.</div>';
  var rem=(remain!=null?'<span style="float:right;color:var(--t3);font-weight:600;font-size:9px;">'+ea(remain)+' req. restantes</span>':'');
  return '<div style="background:rgba(155,89,182,.06);border:1px solid rgba(155,89,182,.2);border-radius:10px;padding:10px;">'
    +'<div style="font-size:10px;font-weight:800;color:#b07cd6;margin-bottom:8px;">📋 PLUS DE MARCHÉS — TES BOOKS'+rem+'</div>'
    +inner
    +'<div style="font-size:9px;color:var(--t3);text-align:center;margin-top:8px;font-style:italic;">Vert = meilleure cote parmi tes books. Source : The Odds API.</div>'
    +'</div>';
}
function _g45Flag(a2){
  if(!a2||a2.length!==2) return '';
  var cc=a2.toUpperCase(); if(!/^[A-Z]{2}$/.test(cc)) return '';
  return String.fromCodePoint(0x1F1E6+cc.charCodeAt(0)-65, 0x1F1E6+cc.charCodeAt(1)-65);
}
function _g45TennisRow(m){
  var h=m.homeTeam||{}, a=m.awayTeam||{};
  var hN=h.shortName||h.name||'?', aN=a.shortName||a.name||'?';
  var hF=_g45Flag(h.country&&h.country.alpha2), aF=_g45Flag(a.country&&a.country.alpha2);
  var hs=m.homeScore||{}, as=m.awayScore||{};
  var st=m.status||{};
  var inprog=(st.type==='inprogress')||st.isInProgress;
  var fin=(st.type==='finished')||st.isFinished;
  var desc=st.description||m.live||'';
  var ts=(m.startTimestamp||m.timestamp||0)*1000;
  var hhmm=ts?new Date(ts).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'';
  var hSet=(hs.current!=null?hs.current:''), aSet=(as.current!=null?as.current:'');
  var score=((inprog||fin)&&hSet!==''&&aSet!=='')?(hSet+'-'+aSet):((inprog||fin)?'·':'vs');
  var hLead=(hSet!==''&&aSet!==''&&hSet>aSet), aLead=(aSet!==''&&hSet!==''&&aSet>hSet);
  var badge=inprog?('🔴 '+desc):(fin?'Terminé':(hhmm||'à venir'));
  var badgeCol=inprog?'#ff4545':(fin?'var(--t3)':'#8aa0ff');
  return '<div onclick="g45ToggleTennis(this)" data-mid="'+m.id+'" style="display:grid;grid-template-columns:1fr auto 1fr 58px;gap:6px;align-items:center;padding:9px 10px;background:'+(inprog?'rgba(255,69,69,.07)':'rgba(255,255,255,.03)')+';border-radius:8px;border-left:3px solid '+(inprog?'#ff4545':'rgba(255,255,255,.1)')+';cursor:pointer;margin-bottom:4px;">'
    +'<div style="font-size:11px;font-weight:'+(hLead?800:700)+';color:var(--t1);text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+hN+' '+hF+'</div>'
    +'<div style="font-size:13px;font-weight:900;color:'+(inprog?'#ff4545':'var(--a)')+';text-align:center;white-space:nowrap;min-width:34px;">'+score+'</div>'
    +'<div style="font-size:11px;font-weight:'+(aLead?800:700)+';color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+aF+' '+aN+'</div>'
    +'<div style="text-align:right;font-size:8px;font-weight:700;color:'+badgeCol+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+badge+'</div>'
    +'</div>'
    +'<div class="smd-panel" style="display:none;"></div>';
}
