  var html=back+'<div class="sec" style="margin-top:0;">🎾 Tableau — '+_g45CyEa(B.maj.label)+' '+B.year+'</div>'+chipsAnnee+tabs
    +matches.map(function(c){ return _g45EspnTennisRow(c); }).join('');
