            var chemin = '/api/v1/schedule?teamId=' + info.id + '&startDate=' + jr + '&endDate=' + jr + '&sportId=1';
            var r = await fetch(FD_PROXY + '?key=mlb&path=' + encodeURIComponent(chemin) + '&host=mlb');
            var d = await r.json();
