/* FICHIER DU DEPOT PRIORITAIRE (22/08), meme principe que `images/equipes/`.
   Antoine voulait le vrai logo de la Formule 1 en fond de sa ligne FORMULE 1 :
   c'est une marque deposee, donc elle n'a rien a faire dans le code source de
   l'app, qui est partagee. Mais rien n'empeche de deposer le fichier soi-meme
   dans son propre depot — le code va le chercher, et le pictogramme dessine ne
   sert plus que de repli tant qu'il n'est pas la.
   Le test d'existence est NON BLOQUANT et memorise : on ne fait pas attendre
   l'affichage du mur pour savoir si un fichier existe. */
/* ═══ LOGO OU PHOTO : LE FICHIER DECIDE (23/08) ═══
   Antoine veut pouvoir deposer indifferemment un logo transparent ou une vraie
   photo de fond. Plutot que de lui imposer un choix ou un nom de fichier
   different, on MESURE l'image une fois chargee : au-dela d'un rapport
   largeur/hauteur de 2,5, c'est une banniere et elle occupe toute la carte ;
   en deca, c'est un pictogramme et il reste centre a taille fixe.
   Le rapport est memorise a cote de l'URL, donc la mesure ne se refait pas. */
/* ═══ LOGO OU PHOTO : C'EST LA TRANSPARENCE QUI TRANCHE (23/08) ═══
   Premiere version : le rapport largeur/hauteur, avec un seuil a 2,5. Mauvais
   critere — la photo de tennis d'Antoine, pas assez large, etait traitee comme
   un pictogramme et restait en petit au milieu, alors qu'il voulait un fond
   plein cadre. Et l'obliger a recadrer ses images pour contenter un seuil
   arbitraire n'a aucun sens.
   Le vrai discriminant est ailleurs : un LOGO a des coins TRANSPARENTS, une
   PHOTO n'en a pas. On dessine donc l'image sur un canevas et on lit le canal
   alpha des quatre coins. Aucune ambiguite, aucune contrainte de format.
   Les fichiers viennent du meme domaine que la page, le canevas n'est donc pas
   souille et la lecture des pixels est autorisee. En cas d'echec — navigateur
   restrictif, image cassee — on retombe sur le rapport, qui reste un repli
   raisonnable. */
var _G45_CAT_SEUIL = 2.5;
function _g45CatFormat(k){
  try{ return localStorage.getItem('g45_catfmt2_' + k) || ''; }catch(e){ return ''; }
}
function _g45CatCoinsTransparents(im){
  try{
    var c = document.createElement('canvas');
    var w = Math.max(2, Math.min(64, im.naturalWidth || 2));
    var h = Math.max(2, Math.min(64, im.naturalHeight || 2));
    c.width = w; c.height = h;
    var x = c.getContext('2d');
    if (!x) return null;
    x.drawImage(im, 0, 0, w, h);
    var coins = [[0,0],[w-1,0],[0,h-1],[w-1,h-1]];
    for (var i = 0; i < coins.length; i++){
      var d = x.getImageData(coins[i][0], coins[i][1], 1, 1).data;
      if (d[3] < 128) return true;          /* un coin translucide suffit */
    }
    return false;
  }catch(e){ return null; }               /* null = indetermine */
}
function _g45CatMesurer(k, url){
  try{
    if (localStorage.getItem('g45_catfmt2_' + k)) return;
    var im = new Image();
    im.crossOrigin = 'anonymous';
    im.onload = function(){
      var t = _g45CatCoinsTransparents(im);
      var fmt;
      if (t === true) fmt = 'logo';
      else if (t === false) fmt = 'banniere';
      else fmt = (((im.naturalWidth || 1) / (im.naturalHeight || 1)) >= _G45_CAT_SEUIL) ? 'banniere' : 'logo';
      try{ localStorage.setItem('g45_catfmt2_' + k, fmt); }catch(e){}
      if(!_g45CatVus['fmt_' + k]){
        _g45CatVus['fmt_' + k] = 1;
        try{ if(typeof render === 'function') render(); }catch(e){}
      }
    };
    im.src = url;
  }catch(e){}
}

var _g45CatVus = {};
function _g45CatPerso(k){
  var cle = 'g45_catimg_' + k;
  var c = null;
  try{ c = localStorage.getItem(cle); }catch(e){}
  /* NEGATIF PERIME (27/08). Un resultat "absent" restait en cache POUR
     TOUJOURS (chaine vide indefinie) : deposer formule1.png dans le depot
     APRES ce premier test ne changeait plus jamais rien, rien ne retestait.
     Constate par Antoine sur FORMULE 1 (fichier present, jamais affiche) et
     AU NRL (image plus la, malgre un nouveau depot). Le negatif expire donc
     desormais au bout de 6h ; le positif (une vraie URL trouvee) reste en
     cache sans limite, aucune raison de re-tester un fichier qui existe deja. */
  if (c !== null && c !== '') {
    /* CORRECTION DU 23/08 : la mesure du format n'etait declenchee qu'a la
       DECOUVERTE du fichier, dans le `onload` du test d'existence. Pour une
       image deja connue — le cas normal des le second chargement — on sortait
       ici sans jamais mesurer, et la detection logo/photo ne tournait pas.
       Constate sur `tennis.png` : le fichier etait bien trouve, le format
       restait `null`. On mesure donc aussi sur ce chemin. */
    try{ _g45CatMesurer(k, c); }catch(e){}
    return c;
  }
  if (c === '') {
    var negT=0; try{ negT=parseInt(localStorage.getItem(cle+'_neg_t')||'0',10)||0; }catch(e){}
    if (negT && (Date.now()-negT) < 6*3600*1000) return c;   /* negatif encore frais */
    /* perime, ou jamais horodate (ancien cache d'avant ce correctif) : on
       retente ci-dessous plutot que de faire confiance a un test qui date. */
  }
  ['png','jpg'].forEach(function(ext){
    var url = 'images/ligues/' + k + '.' + ext;
    var img = new Image();
    img.onload = function(){
      try{ localStorage.setItem(cle, url); localStorage.removeItem(cle+'_neg_t'); }catch(e){}
      try{ _g45CatMesurer(k, url); }catch(e){}
      /* REDESSIN (22/08). Sans lui, le fichier etait bien detecte et memorise,
         mais la ligne restait sur le pictogramme dessine jusqu'au rechargement
         SUIVANT — le test part au moment ou la ligne s'affiche, donc il repond
         toujours trop tard pour ce rendu-la. Constate apres le depot de
         formule1.png : l'image existait, la cle etait bonne, et rien ne
         changeait a l'ecran.
         Garde-fou : on ne redessine qu'une fois par fichier trouve, sinon
         chaque rendu relancerait un test qui relancerait un rendu. */
      if(!_g45CatVus[cle]){
        _g45CatVus[cle] = 1;
        try{ if(typeof render === 'function') render(); }catch(e){}
      }
    };
    img.onerror = function(){
      try{
        var cur = localStorage.getItem(cle);
        if((cur===null || cur==='') && ext==='jpg'){
          localStorage.setItem(cle,'');
          localStorage.setItem(cle+'_neg_t', String(Date.now()));
        }
      }catch(e){}
    };
    img.src = url;
  });
  return c;                                    /* '' ou null = absent pour CE rendu */
}

