  if (/synchro|backup|export|sauvegarde|dropbox|dbx/.test(t) || /g45-sync|pdf-export|dbx-/.test(ids)) return 'donnees';
  if (/\u00e9quipe|unit\u00e9|equipe/.test(t) || /u-search|u-nom|u-add/.test(ids)) return 'eq';
